// The /status/ section: what kayfabe's code has been run on (docs/design/V3_PLATFORM_TESTING.md
// section 9). No dependencies and no URL literals: the API origin, the log origin and the
// repository come from <meta> tags written by site/status_pages.py. Two data sources, kept apart
// on every cell: live rows of the CI Worker's result store (the /v1/ci/ endpoints of the API) and the
// static file coverage.json (evidence imported from committed traces, generated by
// scripts/site/coverage_from_traces.py). Every value from either is inserted with textContent or
// as an encoded query parameter, never as HTML. No GitHub API call is made; commit and evidence
// links are plain hyperlinks.
(() => {
  'use strict';
  const script = document.currentScript;
  const meta = (name) => document.querySelector('meta[name="' + name + '"]')?.content ?? '';
  const mode = meta('kf-status-mode');
  const api = meta('kf-status-api');
  const logs = meta('kf-status-logs');
  const repo = meta('kf-status-repo');
  const root = new URL('../', script.src);
  const fileMode = location.protocol === 'file:';
  const main = document.getElementById('main');
  const state = document.getElementById('kf-status-state');
  const content = document.getElementById('kf-status-content');
  const filters = document.getElementById('kf-status-filters');
  if (!main || !state || !content || (mode !== 'live' && mode !== 'fixture')) return;

  const PATTERN = {
    die: /^[A-Z][A-Z0-9_]{3,7}$/,
    id: /^[a-z0-9][a-z0-9-]{5,63}$/,
    sha: /^[0-9a-f]{40}$/,
    hash: /^[0-9a-f]{64}$/,
    tree: /^[0-9a-f]{64}$/,
    family: /^[a-z][a-z0-9]{2,15}$/,
    tier: /^(?:largest|middle|small|adhoc)$/,
    rev: /^[0-9a-f]{7,40}$/,
    day: /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/,
    path: /^[A-Za-z0-9_][A-Za-z0-9_./-]{0,200}$/,
    logKey: /^runs\/[a-z0-9][a-z0-9-]{5,63}\/[a-z0-9][a-z0-9._-]{0,63}\.(?:log|txt)$/,
  };
  const TIERS = [
    ['largest', 'Largest (release)'],
    ['middle', 'Middle (master PR)'],
    ['small', 'Small'],
    ['adhoc', 'Ad hoc (admin)'],
  ];
  const PLATFORMS = [
    ['linux', 'Linux'],
    ['windows', 'Windows'],
  ];
  const WORKER_LABEL = 'CI Worker run (reproduced)';
  const IMPORTED_LABEL = 'Direct Vast run, evidence in repo (imported)';

  // --- data -----------------------------------------------------------------------------------
  let fixture = null;
  async function load(path) {
    if (mode === 'fixture') {
      if (!fixture) {
        const response = await fetch(new URL(meta('kf-status-fixture'), script.src));
        if (!response.ok) throw new Error('The fixture file could not be read.');
        fixture = (await response.json()).responses ?? {};
      }
      if (!Object.hasOwn(fixture, path))
        throw new Error('This view is not in the synthetic fixture.');
      return fixture[path];
    }
    const response = await fetch(api + path, {
      credentials: 'omit',
      referrerPolicy: 'no-referrer',
      headers: { Accept: 'application/json' },
    });
    if (response.status === 404) throw new Error('Not found.');
    if (!response.ok) throw new Error('The status service answered ' + response.status + '.');
    return response.json();
  }
  // The static evidence file. A missing file costs the imported-evidence lines, never the live ones.
  async function loadCoverage() {
    try {
      const response = await fetch(new URL('coverage.json', script.src), {
        credentials: 'omit',
        referrerPolicy: 'no-referrer',
      });
      if (!response.ok) return null;
      const data = await response.json();
      return data && Array.isArray(data.families) ? data : null;
    } catch {
      return null;
    }
  }

  // --- DOM helpers ----------------------------------------------------------------------------
  function el(tag, attrs, ...children) {
    const node = document.createElement(tag);
    for (const [key, value] of Object.entries(attrs ?? {})) {
      if (value === null || value === undefined || value === false) continue;
      if (key === 'class') node.className = value;
      else node.setAttribute(key, value === true ? '' : String(value));
    }
    for (const child of children.flat(Infinity)) {
      if (child === null || child === undefined || child === false) continue;
      node.append(child instanceof Node ? child : document.createTextNode(String(child)));
    }
    return node;
  }
  const arr = (value) => (Array.isArray(value) ? value : []);
  const text = (value) => (typeof value === 'string' ? value : '');
  const page = (name, params) => {
    const url = new URL(
      'status/' + (name ? name + '/' : '') + (fileMode ? 'index.html' : ''),
      root,
    );
    for (const [key, value] of Object.entries(params ?? {}))
      if (value !== null && value !== undefined && value !== '') url.searchParams.set(key, value);
    return url.href;
  };
  const short = (sha) => (typeof sha === 'string' ? sha.slice(0, 10) : '');
  const commitLink = (sha) =>
    PATTERN.sha.test(sha ?? '')
      ? el('a', { href: repo + '/commit/' + sha, class: 'kf-sha' }, short(sha))
      : el('span', {}, 'unknown commit');
  const revLink = (rev, full) => {
    const target = PATTERN.rev.test(full ?? '') ? full : rev;
    return PATTERN.rev.test(target ?? '')
      ? el('a', { href: repo + '/commit/' + target, class: 'kf-sha' }, String(rev).slice(0, 10))
      : el('span', {}, 'unknown revision');
  };
  const repoPathLink = (path, label) =>
    PATTERN.path.test(path ?? '') && !path.includes('..')
      ? el('a', { href: repo + '/tree/next/' + path }, label)
      : null;
  const when = (iso) =>
    typeof iso === 'string' ? iso.replace('T', ' ').replace(/:00Z$/, 'Z') : '';
  const day = (iso) => (typeof iso === 'string' ? iso.slice(0, 10) : '');
  const VERDICTS = new Set(['PASS', 'FAIL', 'RETRY', 'UNATTRIBUTED']);
  function verdict(value, running) {
    const word = running ? 'running' : VERDICTS.has(value) ? value : 'no data';
    const key = running ? 'running' : VERDICTS.has(value) ? value.toLowerCase() : 'none';
    return el('span', { class: 'kf-v kf-v-' + key }, word);
  }
  function fail(error) {
    state.textContent = error instanceof Error ? error.message : 'Loading failed.';
    state.classList.add('kf-error');
  }
  function done(message) {
    state.textContent = message;
  }
  const query = new URLSearchParams(location.search);
  const param = (name) => {
    const value = query.get(name);
    return value !== null && PATTERN[name]?.test(value) ? value : null;
  };
  const tierLabel = (tier) => TIERS.find(([id]) => id === tier)?.[1] ?? tier;
  const platformLabel = (p) =>
    p === 'both' ? 'Linux and Windows' : p === 'windows' ? 'Windows' : p === 'linux' ? 'Linux' : p;
  const titleCase = (s) => s.charAt(0).toUpperCase() + s.slice(1);

  // --- merging the two sources ----------------------------------------------------------------
  // A live row with platform 'both' covers the Linux and the Windows column (one rental, one
  // verdict over both halves); the newer of the two candidates is the cell's latest.
  const stamp = (run) => text(run?.ended_at) || text(run?.started_at);
  const newest = (a, b) => (!a ? b : !b ? a : stamp(b) > stamp(a) ? b : a);
  function liveFor(cells, family, die, platform) {
    let latest = null;
    let pass = null;
    for (const c of arr(cells)) {
      if (c.family !== family || c.die !== die) continue;
      if (c.platform !== platform && c.platform !== 'both') continue;
      latest = newest(latest, c.latest);
      pass = newest(pass, c.last_pass);
    }
    return { latest, pass };
  }
  function mergedFamilies(coverage, liveCells) {
    const families = [];
    const index = new Map();
    const family = (id, name) => {
      if (!index.has(id)) {
        const entry = { id, name, dies: [], byId: new Map() };
        index.set(id, entry);
        families.push(entry);
      }
      return index.get(id);
    };
    const die = (fam, id) => {
      if (!fam.byId.has(id)) {
        const entry = { id, board: null, cov: null };
        fam.byId.set(id, entry);
        fam.dies.push(entry);
      }
      return fam.byId.get(id);
    };
    for (const f of arr(coverage?.families)) {
      if (!PATTERN.family.test(f.id ?? '')) continue;
      const fam = family(f.id, text(f.name) || titleCase(f.id));
      for (const d of arr(f.dies)) {
        if (!PATTERN.die.test(d.id ?? '')) continue;
        const entry = die(fam, d.id);
        entry.board = text(d.board) || null;
        entry.cov = d;
      }
    }
    const extra = arr(liveCells)
      .filter((c) => PATTERN.family.test(c.family ?? '') && PATTERN.die.test(c.die ?? ''))
      .sort((a, b) => (a.family + a.die).localeCompare(b.family + b.die));
    for (const c of extra) die(family(c.family, titleCase(c.family)), c.die);
    return families;
  }

  // --- cell parts -----------------------------------------------------------------------------
  function counts(group) {
    const parts = [group.pass + ' pass', group.fail + ' fail'];
    if (group.retry) parts.push(group.retry + ' retry');
    if (group.unknown) parts.push(group.unknown + ' see evidence');
    return parts.join(', ') + ' of ' + group.n + (group.n === 1 ? ' run' : ' runs');
  }
  // Imported evidence never shows as a gate verdict: its chip says "evidence", is purple, and the
  // words PASS and FAIL appear only as counts. A Worker-run group (read from the committed job log)
  // shows the verdict word, with its own label.
  function groupChip(group) {
    const clean = group.fail === 0 && group.retry === 0 && group.unknown === 0;
    if (group.source === 'worker_reproduced')
      return clean && group.pass > 0
        ? el('span', { class: 'kf-v kf-v-pass' }, 'PASS')
        : group.fail > 0
          ? el('span', { class: 'kf-v kf-v-fail' }, 'FAIL')
          : el('span', { class: 'kf-v kf-v-retry' }, 'see evidence');
    return el(
      'span',
      { class: 'kf-v kf-imp' + (clean ? '' : group.fail > 0 ? ' kf-imp-fail' : ' kf-imp-unk') },
      'evidence: ' + counts(group),
    );
  }
  function sourceLabel(group) {
    return group.source === 'worker_reproduced' ? WORKER_LABEL : IMPORTED_LABEL;
  }
  function groupBlock(group, full) {
    const worker = group.source === 'worker_reproduced';
    const evidence = repoPathLink(group.evidence, 'evidence');
    const run = PATTERN.path.test(group.run?.path ?? '')
      ? el('a', { href: repo + '/' + group.run.path }, text(group.run.label) || 'run')
      : null;
    const lines = [
      el('span', { class: 'kf-src' }, sourceLabel(group)),
      groupChip(group),
      worker ? el('span', { class: 'kf-small' }, counts(group)) : null,
      el(
        'span',
        { class: 'kf-small' },
        'revision ',
        revLink(group.revision, group.revision_full),
        PATTERN.day.test(group.date ?? '') ? ', ' + group.date : '',
        group.tags && full ? ', runs ' + arr(group.tags).join(', ') : '',
      ),
      group.detail ? el('span', { class: 'kf-small' }, text(group.detail)) : null,
      ...arr(group.notes).map((n) => el('span', { class: 'kf-note' }, text(n))),
      el('span', { class: 'kf-small' }, run, run && evidence ? ', ' : '', evidence),
    ];
    return el('div', { class: 'kf-block kf-block-' + (worker ? 'worker' : 'imported') }, lines);
  }
  function coverageBlocks(cell, full) {
    if (!cell) return [];
    if (cell.state !== 'covered') {
      const see = repoPathLink(cell.see, 'earlier evidence');
      return [
        el(
          'div',
          { class: 'kf-block kf-block-none' },
          el('span', { class: 'kf-v kf-v-none' }, 'not covered'),
          el('span', { class: 'kf-small' }, text(cell.reason)),
          see ? el('span', { class: 'kf-small' }, see) : null,
        ),
      ];
    }
    const groups = arr(cell.groups);
    const shown = full ? groups : groups.slice(0, 1);
    const out = shown.map((g) => groupBlock(g, full));
    if (!full && groups.length > shown.length)
      out.push(
        el(
          'span',
          { class: 'kf-small' },
          '+ ' + (groups.length - shown.length) + ' more at other revisions (see the die page)',
        ),
      );
    if (cell.also) {
      const see = repoPathLink(cell.also_see, 'see');
      out.push(el('span', { class: 'kf-small' }, text(cell.also), ' ', see));
    }
    return out;
  }
  function liveBlock(live, tier) {
    const latest = live.latest;
    if (!latest)
      return el(
        'div',
        { class: 'kf-block kf-block-live' },
        el('span', { class: 'kf-src' }, 'CI Worker store, ' + tierLabel(tier)),
        el('span', { class: 'kf-small' }, 'no run in the store'),
      );
    const running = latest.state === 'running';
    const pass = live.pass;
    return el(
      'div',
      { class: 'kf-block kf-block-live' },
      el('span', { class: 'kf-src' }, 'CI Worker store, ' + tierLabel(latest.tier ?? tier)),
      el(
        'a',
        { href: PATTERN.id.test(latest.id ?? '') ? page('run', { id: latest.id }) : page('', {}) },
        verdict(latest.verdict, running),
      ),
      el(
        'span',
        { class: 'kf-small' },
        'run ',
        PATTERN.id.test(latest.id ?? '')
          ? el('a', { href: page('run', { id: latest.id }) }, latest.id)
          : 'unknown',
        ', commit ',
        commitLink(latest.commit),
        ', ',
        day(running ? latest.started_at : latest.ended_at) || 'date unknown',
        running ? ' (started)' : '',
        latest.platform === 'both' ? ', one run over Linux and Windows' : '',
      ),
      pass && pass.id !== latest.id
        ? el(
            'span',
            { class: 'kf-small' },
            'last pass: ',
            PATTERN.id.test(pass.id ?? '')
              ? el('a', { href: page('run', { id: pass.id }) }, pass.id)
              : 'unknown',
            ', ',
            day(pass.ended_at),
          )
        : null,
    );
  }

  // --- matrix ---------------------------------------------------------------------------------
  function tierNav(selected) {
    return el(
      'nav',
      { 'aria-label': 'Tier', class: 'kf-tabs' },
      el(
        'ul',
        {},
        TIERS.map(([id, label]) =>
          el(
            'li',
            {},
            el(
              'a',
              {
                href: page('', id === 'largest' ? {} : { tier: id }),
                'aria-current': id === selected ? 'page' : null,
              },
              label,
            ),
          ),
        ),
      ),
    );
  }
  function ruleNote(coverage) {
    return el(
      'p',
      { class: 'kf-rule', role: 'note' },
      el('strong', {}, 'Release gate. '),
      text(coverage?.gate_rule) ||
        'Only runs reproduced by the CI Worker count for the release gate. Imported evidence never does.',
    );
  }
  async function matrix() {
    const tier = param('tier') ?? 'largest';
    filters.replaceChildren(tierNav(tier));
    const [coverage, live, trees] = await Promise.all([
      loadCoverage(),
      load('/v1/ci/matrix?tier=' + tier),
      load('/v1/ci/trees?tier=' + tier + '&limit=10').catch(() => null),
    ]);
    const cells = arr(live.cells);
    const sections = mergedFamilies(coverage, cells).map((fam) =>
      el(
        'section',
        { class: 'kf-family-section', 'aria-labelledby': 'fam-' + fam.id },
        el('h2', { id: 'fam-' + fam.id }, fam.name),
        el(
          'div',
          { class: 'kf-scroll', tabindex: 0, role: 'region', 'aria-label': fam.name + ' coverage' },
          el(
            'table',
            { class: 'kf-matrix' },
            el(
              'thead',
              {},
              el(
                'tr',
                {},
                el('th', { scope: 'col' }, 'Die'),
                PLATFORMS.map(([, label]) => el('th', { scope: 'col' }, label + ' guest')),
              ),
            ),
            el(
              'tbody',
              {},
              fam.dies.map((die) =>
                el(
                  'tr',
                  {},
                  el(
                    'th',
                    { scope: 'row' },
                    el('a', { href: page('die', { family: fam.id, die: die.id }) }, die.id),
                    die.board ? el('span', { class: 'kf-small kf-block' }, die.board) : null,
                  ),
                  PLATFORMS.map(([platform]) =>
                    el(
                      'td',
                      { class: 'kf-cell', 'data-label': platformLabel(platform) + ' guest' },
                      liveBlock(liveFor(cells, fam.id, die.id, platform), tier),
                      coverageBlocks(die.cov?.cells?.[platform], false),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
    const parts = [ruleNote(coverage)];
    if (!coverage)
      parts.push(
        el(
          'p',
          { class: 'kf-note' },
          'The imported-evidence file could not be loaded; only live rows are shown.',
        ),
      );
    parts.push(...sections, treeSection(trees, tier), legend());
    content.replaceChildren(...parts);
    done(
      cells.length +
        ' live ' +
        (cells.length === 1 ? 'cell' : 'cells') +
        ' for the ' +
        tierLabel(tier) +
        ' tier. Imported evidence is the same under every tier.',
    );
  }
  function treeSection(trees, tier) {
    const rows = arr(trees?.trees);
    return el(
      'section',
      {},
      el('h2', {}, 'Recent result keys, ' + tierLabel(tier)),
      rows.length
        ? el(
            'div',
            { class: 'kf-scroll', tabindex: 0, role: 'region', 'aria-label': 'Result keys' },
            el(
              'table',
              { class: 'kf-runs' },
              el(
                'thead',
                {},
                el(
                  'tr',
                  {},
                  ['Result key', 'Kind', 'Runs', 'Pass', 'Fail', 'Running', 'Last run'].map((h) =>
                    el('th', { scope: 'col' }, h),
                  ),
                ),
              ),
              el(
                'tbody',
                {},
                rows.map((t) =>
                  el(
                    'tr',
                    {},
                    el(
                      'td',
                      {},
                      PATTERN.hash.test(t.hash ?? '')
                        ? el(
                            'a',
                            { href: page('commit', { tree: t.hash }), class: 'kf-sha' },
                            t.hash.slice(0, 12),
                          )
                        : 'unknown',
                    ),
                    el('td', {}, text(t.kind)),
                    el('td', {}, String(t.runs ?? '')),
                    el('td', {}, String(t.passed ?? '')),
                    el('td', {}, String(t.failed ?? '')),
                    el('td', {}, String(t.running ?? '')),
                    el('td', {}, when(t.last_at)),
                  ),
                ),
              ),
            ),
          )
        : el('p', {}, 'No runs recorded for this tier yet.'),
    );
  }
  function legend() {
    return el(
      'section',
      { class: 'kf-legend-box' },
      el('h2', {}, 'How to read this'),
      el(
        'ul',
        { class: 'kf-legend' },
        el(
          'li',
          {},
          el('span', { class: 'kf-src' }, 'CI Worker store, <tier>'),
          ': the newest run in the CI Worker’s result store for that tier, with its verdict ',
          ['PASS', 'FAIL', 'RETRY', 'UNATTRIBUTED'].map((v) => [verdict(v, false), ' ']),
          verdict(null, true),
          ' ',
          verdict(null, false),
          '. RETRY and UNATTRIBUTED never pass. Run, commit and date are on every row.',
        ),
        el(
          'li',
          {},
          el('span', { class: 'kf-src' }, WORKER_LABEL),
          ': a run of the CI Worker whose job log is committed in the repository. It is shown with ' +
            'its run, revision and date. It is read from the log, not from the result store.',
        ),
        el(
          'li',
          {},
          el('span', { class: 'kf-src' }, IMPORTED_LABEL),
          ': a run made by hand on a rented Vast box, with its logs committed under traces/. ',
          el('span', { class: 'kf-v kf-imp' }, 'evidence: 2 pass, 0 fail of 2 runs'),
          ' counts runs; it is not a verdict and never counts for the release gate.',
        ),
        el(
          'li',
          {},
          el('span', { class: 'kf-v kf-v-none' }, 'not covered'),
          ': no run; the reason is the one the repository states.',
        ),
        el(
          'li',
          {},
          'A Linux run means the Linux bar (v3 gates, bare-metal and thin-guest suites, birth census); a Windows run means the Windows gate. A live run over both platforms appears in both columns.',
        ),
        el(
          'li',
          {},
          'Tiers: largest (release), middle (master PR), small (driver matrix), ad hoc (admin start).',
        ),
      ),
    );
  }

  // --- die ------------------------------------------------------------------------------------
  async function die() {
    const family = param('family');
    const id = param('die');
    if (!family || !id) throw new Error('This page needs a family and a die.');
    const [coverage, live] = await Promise.all([
      loadCoverage(),
      load('/v1/ci/matrix?family=' + family),
    ]);
    const entry = arr(coverage?.families)
      .find((f) => f.id === family)
      ?.dies?.find((d) => d.id === id);
    main.querySelector('h1').textContent = id + (entry?.board ? ' (' + entry.board + ')' : '');
    const cells = arr(live.cells).filter((c) => c.die === id && c.family === family);
    const sections = PLATFORMS.map(([platform, label]) => {
      const cell = entry?.cells?.[platform];
      return el(
        'section',
        {},
        el('h2', {}, label + ' guest: evidence in the repository'),
        ...(cell
          ? coverageBlocks(cell, true)
          : [el('p', {}, 'No imported evidence for this die.')]),
      );
    });
    const rows = cells
      .sort((a, b) => (a.tier + a.platform).localeCompare(b.tier + b.platform))
      .map((c) =>
        el(
          'tr',
          {},
          el('td', {}, tierLabel(c.tier)),
          el('td', {}, platformLabel(c.platform)),
          el('td', {}, verdictLink(c.latest)),
          el('td', {}, commitLink(c.latest?.commit)),
          el('td', {}, when(c.latest?.ended_at ?? c.latest?.started_at)),
          el(
            'td',
            {},
            c.last_pass
              ? [
                  el('a', { href: page('run', { id: c.last_pass.id }) }, text(c.last_pass.id)),
                  ', ',
                  day(c.last_pass.ended_at),
                ]
              : 'none',
          ),
        ),
      );
    const liveSection = el(
      'section',
      {},
      el('h2', {}, 'CI Worker store: newest run per tier and platform'),
      rows.length
        ? el(
            'div',
            { class: 'kf-scroll', tabindex: 0, role: 'region', 'aria-label': 'Live runs' },
            el(
              'table',
              { class: 'kf-runs' },
              el(
                'thead',
                {},
                el(
                  'tr',
                  {},
                  ['Tier', 'Platform', 'Latest run', 'Commit', 'Finished', 'Last pass'].map((h) =>
                    el('th', { scope: 'col' }, h),
                  ),
                ),
              ),
              el('tbody', {}, rows),
            ),
          )
        : el('p', {}, 'The result store has no run for this die yet.'),
    );
    content.replaceChildren(
      el('p', {}, el('a', { href: page('', {}) }, 'Back to the matrix')),
      ruleNote(coverage),
      liveSection,
      ...sections,
    );
    done(
      rows.length +
        (rows.length === 1 ? ' live row' : ' live rows') +
        '. Imported evidence lists every revision it was run at.',
    );
  }
  function verdictLink(run) {
    if (!run) return 'none';
    const chip = verdict(run.verdict, run.state === 'running');
    return PATTERN.id.test(run.id ?? '')
      ? el('a', { href: page('run', { id: run.id }) }, chip, ' ', run.id)
      : chip;
  }

  // --- run ------------------------------------------------------------------------------------
  function sourceText(source) {
    return source === 'reproduced' ? WORKER_LABEL : text(source) || 'unknown';
  }
  function stageChip(result) {
    if (result === 'SKIP') return el('span', { class: 'kf-v kf-v-none' }, 'skipped');
    if (result === 'NOT_RUN') return el('span', { class: 'kf-v kf-v-none' }, 'not run');
    return verdict(result, false);
  }
  function logLink(log) {
    if (!log || !PATTERN.logKey.test(log.key ?? '')) return el('p', {}, 'No public log.');
    // Only the configured log origin is linked; the API's own `direct` field is accepted only when
    // it is that origin plus the key.
    const direct = typeof log.direct === 'string' ? log.direct : '';
    const href = logs ? logs + '/' + log.key : '';
    if (href && (!direct || direct === href))
      return el('p', {}, el('a', { href, type: 'text/plain' }, log.key));
    return el('p', {}, 'Log object ', el('code', {}, log.key), ' (no log origin is configured).');
  }
  async function run() {
    const id = param('id');
    if (!id) throw new Error('This page needs a run id.');
    const data = (await load('/v1/ci/runs/' + id)).run;
    if (!data) throw new Error('Not found.');
    main.querySelector('h1').textContent = 'Run ' + text(data.id);
    const running = data.state === 'running';
    const drivers = Object.entries(data.host?.drivers ?? {});
    const facts = [
      ['Verdict', verdict(data.verdict, running)],
      ['Source', sourceText(data.source)],
      ['Tier', tierLabel(text(data.tier))],
      ['Profile', text(data.profile)],
      ['Platform', platformLabel(text(data.platform))],
      [
        'Die',
        PATTERN.die.test(data.die ?? '') && PATTERN.family.test(data.family ?? '')
          ? el(
              'a',
              { href: page('die', { family: data.family, die: data.die }) },
              data.die + ' (' + data.family + ')',
            )
          : '',
      ],
      ['GPU', text(data.host?.gpu_name)],
      [
        'Commit',
        [
          commitLink(data.commit),
          ' ',
          el('a', { href: page('commit', { sha: data.commit }) }, 'results for this commit'),
        ],
      ],
      [
        'Result key',
        PATTERN.hash.test(data.tree?.hash ?? '')
          ? [
              el(
                'a',
                { href: page('commit', { tree: data.tree.hash }), class: 'kf-sha' },
                data.tree.hash.slice(0, 16),
              ),
              ' (',
              text(data.tree.kind),
              ')',
            ]
          : '',
      ],
      ['Started', when(data.started_at)],
      ['Finished', when(data.ended_at) || 'in flight'],
    ];
    for (const [name, version] of drivers) facts.push([name + ' driver', String(version)]);
    const stages = arr(data.stages);
    content.replaceChildren(
      el('p', {}, el('a', { href: page('', {}) }, 'Back to the matrix')),
      el(
        'dl',
        { class: 'kf-facts' },
        facts.map(([k, v]) => [el('dt', {}, k), el('dd', {}, v)]),
      ),
      el('h2', {}, 'Stages'),
      stages.length
        ? el(
            'div',
            { class: 'kf-scroll', tabindex: 0, role: 'region', 'aria-label': 'Stages' },
            el(
              'table',
              { class: 'kf-runs' },
              el(
                'thead',
                {},
                el(
                  'tr',
                  {},
                  ['Stage', 'Result', 'Exit code', 'Duration'].map((h) =>
                    el('th', { scope: 'col' }, h),
                  ),
                ),
              ),
              el(
                'tbody',
                {},
                stages.map((s) =>
                  el(
                    'tr',
                    {},
                    el('td', {}, text(s.name)),
                    el('td', {}, stageChip(s.result)),
                    el('td', {}, s.rc === null || s.rc === undefined ? '' : String(s.rc)),
                    el(
                      'td',
                      {},
                      Number.isFinite(s.duration_ms)
                        ? (s.duration_ms / 60000).toFixed(1) + ' min'
                        : '',
                    ),
                  ),
                ),
              ),
            ),
          )
        : el('p', {}, 'No stages recorded.'),
      el('h2', {}, 'Log'),
      logLink(data.log),
    );
    done(running ? 'This run is still in flight.' : 'This run is final.');
  }

  // --- commit and result key ------------------------------------------------------------------
  function runsTable(runs, current) {
    return el(
      'div',
      { class: 'kf-scroll', tabindex: 0, role: 'region', 'aria-label': 'Runs' },
      el(
        'table',
        { class: 'kf-runs' },
        el(
          'thead',
          {},
          el(
            'tr',
            {},
            ['Run', 'Verdict', 'Die', 'Platform', 'Tier', 'Commit', 'Finished'].map((h) =>
              el('th', { scope: 'col' }, h),
            ),
          ),
        ),
        el(
          'tbody',
          {},
          runs.map((r) =>
            el(
              'tr',
              {},
              el(
                'td',
                {},
                PATTERN.id.test(r.id ?? '')
                  ? el('a', { href: page('run', { id: r.id }) }, r.id)
                  : 'unknown',
              ),
              el('td', {}, verdict(r.verdict, r.state === 'running')),
              el(
                'td',
                {},
                PATTERN.die.test(r.die ?? '') && PATTERN.family.test(r.family ?? '')
                  ? el('a', { href: page('die', { family: r.family, die: r.die }) }, r.die)
                  : '',
              ),
              el('td', {}, platformLabel(text(r.platform))),
              el('td', {}, tierLabel(text(r.tier))),
              el(
                'td',
                {},
                commitLink(r.commit),
                r.other_commit || (current && r.commit !== current)
                  ? el('span', { class: 'kf-small kf-block' }, 'another commit, same result key')
                  : null,
              ),
              el('td', {}, when(r.ended_at) || 'in flight'),
            ),
          ),
        ),
      ),
    );
  }
  const KEY_KINDS =
    'Result key kinds: tree is computed by the CI Worker from the commit’s files after its .workerignore; claimed was supplied by a caller and never answers for another commit; commit means no tree key could be computed.';
  async function commit() {
    const sha = param('sha');
    const tree = param('tree');
    if (!sha && !tree) throw new Error('This page needs a 40-digit commit id or a result key.');
    const back = el('p', {}, el('a', { href: page('', {}) }, 'Back to the matrix'));
    if (sha) {
      const data = await load('/v1/ci/commits/' + sha);
      main.querySelector('h1').textContent = 'Commit ' + short(sha);
      const runs = arr(data.runs);
      content.replaceChildren(
        back,
        el('p', {}, commitLink(sha), ' on GitHub.'),
        el('h2', {}, 'Result keys'),
        el(
          'ul',
          {},
          arr(data.trees).map((t) =>
            el(
              'li',
              {},
              PATTERN.hash.test(t.hash ?? '')
                ? el(
                    'a',
                    { href: page('commit', { tree: t.hash }), class: 'kf-sha' },
                    t.hash.slice(0, 16),
                  )
                : 'unknown',
              ' (' + text(t.kind) + '), ' + (t.runs ?? 0) + ' runs, last ' + when(t.last_at),
            ),
          ),
        ),
        el('p', { class: 'kf-small' }, KEY_KINDS),
        el('h2', {}, 'Runs'),
        runs.length ? runsTable(runs, sha) : el('p', {}, 'No runs.'),
      );
      done(runs.length + ' runs under this commit’s result keys.');
      return;
    }
    const data = await load('/v1/ci/trees/' + tree);
    main.querySelector('h1').textContent = 'Result key ' + tree.slice(0, 12);
    const runs = arr(data.runs);
    content.replaceChildren(
      back,
      el('p', {}, 'Kind: ' + text(data.tree?.kind) + '.'),
      el('p', { class: 'kf-small' }, KEY_KINDS),
      el('h2', {}, 'Commits recorded under this key'),
      el(
        'ul',
        {},
        arr(data.commits).map((c) =>
          el(
            'li',
            {},
            PATTERN.sha.test(c.sha ?? '')
              ? [
                  el('a', { href: page('commit', { sha: c.sha }) }, short(c.sha)),
                  ' ',
                  commitLink(c.sha),
                ]
              : 'unknown',
            ', ' + (c.runs ?? 0) + ' runs, last ' + when(c.last_at),
          ),
        ),
      ),
      el('h2', {}, 'Runs'),
      runs.length ? runsTable(runs, null) : el('p', {}, 'No runs.'),
    );
    done(runs.length + ' runs under this result key.');
  }

  const views = { matrix, die, run, commit };
  const view = views[main.dataset.page];
  if (view) view().catch(fail);
})();
